// Headset pose <-> robot head pose. Pure maths, no Unity: port of xr-client/pages/pose.js, checked against it in
// Assets/Tests (values generated by running pose.js).
//
// Frames:
//   Unity: x right, y up, z forward (left-handed).   WebXR: x right, y up, z back.   Robot: x forward, y left, z up.
//   WebXR (x, y, z, w) = Unity (-x, -y, z, w); robot (x, y, z) = (-xr.z, -xr.x, xr.y)
// Angles: degrees, Euler ZYX as in the SDK (R = Rz(yaw) Ry(pitch) Rx(roll)):
//   yaw + = look left, pitch + = look down, roll + = tilt right.
// Quaternions: unit length, in the WebXR frame unless the name says otherwise.

using System;
using System.Globalization;

public struct Quat
{
    public double X, Y, Z, W;

    public Quat(double x, double y, double z, double w) { X = x; Y = y; Z = z; W = w; }

    public static readonly Quat Identity = new Quat(0, 0, 0, 1);

    public static Quat operator *(Quat a, Quat b) => new Quat(
        a.W * b.X + a.X * b.W + a.Y * b.Z - a.Z * b.Y,
        a.W * b.Y - a.X * b.Z + a.Y * b.W + a.Z * b.X,
        a.W * b.Z + a.X * b.Y - a.Y * b.X + a.Z * b.W,
        a.W * b.W - a.X * b.X - a.Y * b.Y - a.Z * b.Z);

    public Quat Inverse => new Quat(-X, -Y, -Z, W);

    /// <summary>Unity rotation to the same rotation in the WebXR frame.</summary>
    public static Quat FromUnity(double x, double y, double z, double w) => new Quat(-x, -y, z, w);
}

public struct RobotAngles
{
    public double Roll, Pitch, Yaw;

    public RobotAngles(double roll, double pitch, double yaw) { Roll = roll; Pitch = pitch; Yaw = yaw; }
}

public static class PoseMath
{
    public const double Deg = 180 / Math.PI;

    /// <summary>Headset rotation (WebXR frame, relative to "straight ahead") to robot head angles in degrees.</summary>
    public static RobotAngles HeadsetToRobot(Quat q)
    {
        double w = q.W, x = -q.Z, y = -q.X, z = q.Y;
        double r00 = 1 - 2 * (y * y + z * z), r10 = 2 * (x * y + w * z);
        double r20 = 2 * (x * z - w * y), r21 = 2 * (y * z + w * x), r22 = 1 - 2 * (x * x + y * y);
        return new RobotAngles(
            Math.Atan2(r21, r22) * Deg,
            Math.Asin(Math.Max(-1, Math.Min(1, -r20))) * Deg,
            Math.Atan2(r10, r00) * Deg);
    }

    /// <summary>Inverse of HeadsetToRobot.</summary>
    public static Quat RobotToHeadset(double rollDeg, double pitchDeg, double yawDeg)
    {
        var q = Axis(0, 0, 1, yawDeg / Deg) * Axis(0, 1, 0, pitchDeg / Deg) * Axis(1, 0, 0, rollDeg / Deg);
        return new Quat(-q.Y, q.Z, -q.X, q.W);
    }

    static Quat Axis(double ax, double ay, double az, double rad)
    {
        double s = Math.Sin(rad / 2);
        return new Quat(ax * s, ay * s, az * s, Math.Cos(rad / 2));
    }
}

/// <summary>"Straight ahead" of the user. Everything the robot does is relative to this.</summary>
public class Recenter
{
    Quat q0 = Quat.Identity, q0Inv = Quat.Identity;

    public void Set(Quat q) { q0 = q; q0Inv = q.Inverse; }
    public Quat ToRelative(Quat world) => q0Inv * world;
    public Quat ToWorld(Quat relative) => q0 * relative;
}

/// <summary>
/// Moves towards a target with limited velocity and acceleration (degrees, seconds). Brakes early enough to stop at
/// the target, so fast head turns become a quick but smooth robot motion, not a jerk that can tip the robot over.
/// </summary>
public class RateLimiter
{
    readonly double maxVel, maxAcc;

    public double Pos, Vel;

    public RateLimiter(double maxVel, double maxAcc) { this.maxVel = maxVel; this.maxAcc = maxAcc; }

    public double Step(double target, double dt)
    {
        double err = target - Pos;
        // Fastest speed from which we can still brake to zero within the remaining distance.
        double vStop = Math.Sqrt(2 * maxAcc * Math.Abs(err));
        double vWant = Math.Sign(err) * Math.Min(Math.Min(maxVel, vStop), Math.Abs(err) / dt);
        double dv = Math.Max(-maxAcc * dt, Math.Min(maxAcc * dt, vWant - Vel));
        Vel += dv;
        Pos += Vel * dt;
        return Pos;
    }
}

public struct HeadTarget
{
    public double Roll, Pitch, Yaw, BodyYaw;

    /// <summary>FullBodyTarget message for the daemon's set_target (radians, antennas at rest).</summary>
    public string ToDaemonJson() =>
        "{\"target_head_pose\":{\"roll\":" + Rad(Roll) + ",\"pitch\":" + Rad(Pitch) + ",\"yaw\":" + Rad(Yaw) +
        "},\"target_antennas\":[0,0],\"target_body_yaw\":" + Rad(BodyYaw) + "}";

    static string Rad(double deg) => (deg / PoseMath.Deg).ToString("R", CultureInfo.InvariantCulture);
}

/// <summary>
/// Same pipeline as robot/src/reachy_meetings_robot (head_mirror + safety): exponential smoothing -> clamp ->
/// velocity/acceleration limit -> body follows (slower) when head yaw leaves the head/body window.
/// </summary>
public class HeadMirror
{
    // Meeting limits (degrees), tighter than the hardware (pitch/roll ±40). PitchUp 35: someone standing or close to
    // the robot on the table is up to ~30° above it. PitchDown: table, papers, laptop. Yaw/body: free to look around.
    const double LimRoll = 15, LimPitchUp = 35, LimPitchDown = 20, LimYaw = 180, LimBody = 160, LimHeadBody = 65;
    // deg/s and deg/s². The body is the heavy part: it turns slower and gentler than the head.
    const double HeadVel = 150, HeadAcc = 800, BodyVel = 90, BodyAcc = 300;

    readonly double smoothing;
    readonly double[] filt = new double[3];
    readonly RateLimiter[] head =
    {
        new RateLimiter(HeadVel, HeadAcc), new RateLimiter(HeadVel, HeadAcc), new RateLimiter(HeadVel, HeadAcc),
    };
    readonly RateLimiter body = new RateLimiter(BodyVel, BodyAcc);
    double bodyGoal;

    public HeadMirror(double smoothing = 0.35) { this.smoothing = smoothing; }

    static double Clamp(double v, double lo, double hi) => Math.Max(lo, Math.Min(hi, v));

    public HeadTarget Step(RobotAngles raw, double dt)
    {
        dt = Clamp(dt > 0 ? dt : 0.02, 0.001, 0.1);
        double a = smoothing;
        filt[0] = a * filt[0] + (1 - a) * raw.Roll;
        filt[1] = a * filt[1] + (1 - a) * raw.Pitch;
        filt[2] = a * filt[2] + (1 - a) * raw.Yaw;
        double goalRoll = Clamp(filt[0], -LimRoll, LimRoll);
        double goalPitch = Clamp(filt[1], -LimPitchUp, LimPitchDown);   // pitch + = look down
        double goalYaw = Clamp(filt[2], -LimYaw, LimYaw);
        double roll = head[0].Step(goalRoll, dt), pitch = head[1].Step(goalPitch, dt);
        double yawWanted = head[2].Step(goalYaw, dt);
        // Body goal from where the user looks (not from the rate-limited head), so it starts turning at once.
        if (goalYaw > bodyGoal + LimHeadBody) bodyGoal = goalYaw - LimHeadBody;
        if (goalYaw < bodyGoal - LimHeadBody) bodyGoal = goalYaw + LimHeadBody;
        bodyGoal = Clamp(bodyGoal, -LimBody, LimBody);
        double bodyYaw = body.Step(bodyGoal, dt);
        // While the body is still catching up, the head waits at the edge of the window.
        double yaw = Clamp(yawWanted, bodyYaw - LimHeadBody, bodyYaw + LimHeadBody);
        if (yaw != yawWanted) { head[2].Pos = yaw; head[2].Vel = body.Vel; }
        return new HeadTarget { Roll = roll, Pitch = pitch, Yaw = yaw, BodyYaw = bodyYaw };
    }
}
